1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8" />
5	<meta name="viewport" content="width=device-width, initial-scale=1" />
6	<title>My Bookmarks</title>
7	<style>
8	  :root {
9	    --ink: #1f2328;
10	    --muted: #6b7280;
11	    --line: #e5e7eb;
12	    --accent: #2563eb;
13	    --bg: #f7f8fa;
14	  }
15	  * { box-sizing: border-box; }
16	  body {
17	    margin: 0;
18	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
19	    color: var(--ink);
20	    background: var(--bg);
21	  }
22	  .wrap { max-width: 720px; margin: 0 auto; padding: 32px 20px 80px; }
23	  h1 { font-size: 22px; margin: 0 0 4px; }
24	  .sub { color: var(--muted); margin: 0 0 24px; font-size: 14px; }
25	  .search {
26	    position: sticky; top: 0; background: var(--bg); padding: 12px 0 16px; z-index: 2;
27	  }
28	  .search input {
29	    width: 100%; font-size: 17px; padding: 14px 16px; border: 1px solid var(--line);
30	    border-radius: 10px; outline: none; background: #fff;
31	  }
32	  .search input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(37,99,235,.12); }
33	  .count { color: var(--muted); font-size: 13px; margin: 4px 2px 14px; }
34	  ul { list-style: none; margin: 0; padding: 0; }
35	  li {
36	    background: #fff; border: 1px solid var(--line); border-radius: 10px;
37	    padding: 14px 16px; margin-bottom: 10px;
38	  }
39	  .title { font-size: 16px; font-weight: 600; margin: 0 0 3px; }
40	  .title a { color: var(--ink); text-decoration: none; }
41	  .title a:hover { text-decoration: underline; }
42	  .site { color: var(--accent); font-size: 12px; margin: 0 0 6px; }
43	  .desc { color: #374151; font-size: 14px; margin: 0 0 8px; line-height: 1.45; }
44	  .date { color: var(--muted); font-size: 12px; }
45	  mark { background: #fde68a; color: inherit; padding: 0 1px; border-radius: 2px; }
46	  .empty { color: var(--muted); text-align: center; padding: 48px 12px; }
47	  .empty strong { color: var(--ink); }
48	</style>
49	</head>
50	<body>
51	  <div class="wrap">
52	    <h1>My Bookmarks</h1>
53	    <p class="sub">Everything you've saved, all in one place.</p>
54	
55	    <div class="search">
56	      <input id="q" type="text" placeholder="Search your bookmarks…" autocomplete="off" autofocus />
57	    </div>
58	    <div class="count" id="count"></div>
59	
60	    <ul id="list"></ul>
61	    <div class="empty" id="empty" style="display:none;"></div>
62	  </div>
63	
64	<script>
65	  // Seeded so the "finding" experience can be shown.
66	  const bookmarks = [
67	    {
68	      title: "The best way to cook pasta, according to science",
69	      site: "seriouseats.com",
70	      desc: "Why you don't need a huge pot of water, and how much salt actually matters when boiling pasta.",
71	      date: "Saved 3 weeks ago"
72	    },
73	    {
74	      title: "A slow-roasted tomato sauce worth the wait",
75	      site: "smittenkitchen.com",
76	      desc: "A weekend recipe: roast the tomatoes low and slow for a deep, sweet sauce. Great over any pasta.",
77	      date: "Saved 2 months ago"
78	    },
79	    {
80	      title: "How to structure a large React application",
81	      site: "martinfowler.com",
82	      desc: "Folder structure, state management, and where to draw module boundaries as a front-end project grows.",
83	      date: "Saved 5 days ago"
84	    },
85	    {
86	      title: "CSS Grid: a complete visual guide",
87	      site: "css-tricks.com",
88	      desc: "A reference for the grid layout properties with diagrams. Good to keep open while building layouts.",
89	      date: "Saved 1 month ago"
90	    },
91	    {
92	      title: "The psychology of why we procrastinate",
93	      site: "theatlantic.com",
94	      desc: "A long read on why we put things off, and what actually helps. Been meaning to finish this one.",
95	      date: "Saved 6 weeks ago"
96	    },
97	    {
98	      title: "Understanding database indexes for beginners",
99	      site: "planetscale.com",
100	      desc: "Reference material for a side project: what an index is, when it helps, and the cost of adding one.",
101	      date: "Saved 2 weeks ago"
102	    },
103	    {
104	      title: "A no-knead bread recipe anyone can make",
105	      site: "nytimes.com",
106	      desc: "Four ingredients, no kneading, overnight rise. The crustiest loaf from a home oven.",
107	      date: "Saved 4 months ago"
108	    }
109	  ];
110	
111	  const list = document.getElementById('list');
112	  const empty = document.getElementById('empty');
113	  const count = document.getElementById('count');
114	  const q = document.getElementById('q');
115	
116	  function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
117	  function highlight(text, term){
118	    const safe = escapeHtml(text);
119	    if(!term) return safe;
120	    const re = new RegExp('('+term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig');
121	    return safe.replace(re,'<mark>$1</mark>');
122	  }
123	
124	  function render(term){
125	    const t = term.trim().toLowerCase();
126	    const matches = bookmarks.filter(b =>
127	      !t || b.title.toLowerCase().includes(t) || b.desc.toLowerCase().includes(t)
128	    );
129	
130	    if(matches.length === 0){
131	      list.innerHTML = '';
132	      empty.style.display = 'block';
133	      empty.innerHTML = 'Nothing matched <strong>"'+escapeHtml(term.trim())+'"</strong>.';
134	      count.textContent = '';
135	      return;
136	    }
137	    empty.style.display = 'none';
138	    count.textContent = t
139	      ? matches.length + (matches.length===1?' match':' matches')
140	      : matches.length + ' bookmarks';
141	
142	    list.innerHTML = matches.map(b => `
143	      <li>
144	        <p class="title"><a href="#" onclick="return false;">${highlight(b.title, t)}</a></p>
145	        <p class="site">${escapeHtml(b.site)}</p>
146	        <p class="desc">${highlight(b.desc, t)}</p>
147	        <p class="date">${escapeHtml(b.date)}</p>
148	      </li>
149	    `).join('');
150	  }
151	
152	  q.addEventListener('input', e => render(e.target.value));
153	  render('');
154	</script>
155	</body>
156	</html>
