277	    tagbar.innerHTML = (allTags.length?'<span class="label">Round up:</span>':'') + allTags.map(t=>
278	      `<button class="filter ${t===activeTag?'on':''}" data-tag="${escapeHtml(t)}">${escapeHtml(t)}</button>`).join('')
