280	    tagbar.querySelectorAll('.filter').forEach(el=>el.addEventListener('click',()=>{ const t=el.getAttribute('data-tag'); activeTag=(activeTag===t)?null:t; render(); }));
281	    const cb=$('clearBtn'); if(cb) cb.addEventListener('click',()=>{ activeTag=null; render(); });
282	  }
283	
284	  function render(){
285	    const term=q.value;
286	    const tokens=term.trim().toLowerCase().split(/\s+/).filter(Boolean);
287	    const tokenRes=tokens.map(tok=>new RegExp('\\b'+esc(tok),'i'));
288	    const matches=bookmarks.filter(b=>{
289	      if(activeTag && !b.tags.includes(activeTag)) return false;
290	      if(!tokens.length) return true;
291	      const hay=(b.title+' '+b.desc+' '+(b.note||'')+' '+b.source+' '+b.site).toLowerCase();
292	      return tokenRes.every(re=>re.test(hay));
293	    });
294	    renderTagbar();
295	
296	    if(matches.length===0){
297	      list.innerHTML=''; empty.style.display='block'; empty.innerHTML='Nothing to show for that.'; count.textContent=''; return;
298	    }
299	    empty.style.display='none';
300	    count.textContent = matches.length + (matches.length===1?' bookmark':' bookmarks') + (activeTag?' tagged "'+escapeHtml(activeTag)+'"':'');
301	
302	    list.innerHTML = matches.map(b=>`
303	      <li class="${b._fresh?'fresh':''}" data-url="${escapeHtml(b.url||'')}">
304	        <div class="card-head">
305	          <p class="title"><a href="#" onclick="return false;">${highlight(b.title,tokens)}</a></p>
306	          <button class="edit-btn" data-url="${escapeHtml(b.url||'')}">Edit</button>
307	        </div>
308	        <p class="site">${highlight(b.source,tokens)}</p>
309	        ${b.desc?`<p class="desc">${highlight(b.desc,tokens)}</p>`:''}
310	        ${b.note?`<p class="desc" style="border-left:3px solid #c7d2fe; padding-left:10px; color:#3730a3;"><em>${highlight(b.note,tokens)}</em></p>`:''}
311	        <p class="date">${escapeHtml(b.date)}</p>
312	        <div class="tags">${b.tags.map(t=>`<span class="tag ${t===activeTag?'on':''}" data-tag="${escapeHtml(t)}">${escapeHtml(t)}</span>`).join('')}</div>
313	      </li>`).join('');
314	    list.querySelectorAll('.tag').forEach(el=>el.addEventListener('click',()=>{ const t=el.getAttribute('data-tag'); activeTag=(activeTag===t)?null:t; render(); window.scrollTo({top:0,behavior:'smooth'}); }));
