155	
156	  function normUrl(u){ return u.trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/+$/,''); }
157	  function findExisting(u, except){ const n=normUrl(u); if(!n) return null; return bookmarks.find(b=>b!==except && b.url && normUrl(b.url)===n); }
158	
159	  const fetchMock = [
160	    { match:"smittenkitchen", title:"The best olive oil cake, ever", source:"Smitten Kitchen", desc:"A one-bowl olive oil cake with a crackly top — plush, citrusy, and impossible to mess up." },
161	    { match:"nytimes", title:"A weeknight sheet-pan chicken dinner", source:"The New York Times", desc:"Everything roasts on one tray: chicken thighs, potatoes and lemon. Minimal cleanup." },
