342	  function render(){
343	    renderAsideBar();
344	    if(viewMode==='aside'){ renderAside(); return; }
345	    $('searchBar').style.display='';
346	    const term=q.value;
347	    const tokens=term.trim().toLowerCase().split(/\s+/).filter(Boolean);
348	    const tokenRes=tokens.map(tok=>new RegExp('\\b'+esc(tok),'i'));
349	    const matches=bookmarks.filter(b=>{
