84	  .add-label { font-size:12px; padding:3px 9px; border-radius:999px; background:#fff; color:#64748b; border:1px dashed #cbd5e1; cursor:pointer; }
85	  .add-label:hover { border-color:var(--accent); color:var(--accent); }
