92	<body>
93	  <div class="wrap">
94	    <div class="top">
95	      <div>
96	        <h1>My Bookmarks</h1>
97	        <p class="sub">Everything you've saved, all in one place.</p>
98	      </div>
99	      <button class="add-btn" id="addBtn">＋ Add bookmark</button>
100	    </div>
101	
102	    <div id="asideBar" style="margin:-8px 0 16px; font-size:13px;"></div>
103	
104	    <div class="adder" id="adder">
105	      <h2 id="adderTitle">Save a new bookmark</h2>
106	      <div class="field">
107	        <label id="urlLabel">Paste the link</label>
108	        <input id="url" type="text" placeholder="https://…" autocomplete="off" />
109	      </div>
110	
111	      <div class="dupe" id="dupe" style="display:none; background:#fff7ed; border:1px solid #fed7aa; color:#9a3412; padding:12px; border-radius:8px; margin:0 0 12px; font-size:14px;">
112	        <span id="dupeText"></span>
113	        <button id="openExisting" style="border:none; background:#fdba74; color:#7c2d12; border-radius:6px; padding:4px 10px; cursor:pointer; margin-left:8px; font-size:13px;">Open it to make changes</button>
114	      </div>
115	
116	      <div class="preview" id="preview">
117	        <div class="field">
118	          <label>Title <span class="autofilled" id="tFill"></span></label>
119	          <input id="fTitle" type="text" />
120	        </div>
121	        <div class="field">
122	          <label>Site <span class="autofilled" id="sFill"></span></label>
123	          <input id="fSite" type="text" />
124	        </div>
125	        <div class="field">
126	          <label>What it's about, from the page <span class="autofilled" id="dFill"></span></label>
127	          <textarea id="fDesc"></textarea>
128	        </div>
129	        <div class="field">
130	          <label>Your own note (optional) — in your words, so you can find it your way later</label>
131	          <textarea id="fNote" placeholder="e.g. the cake I'm making for Sarah's birthday"></textarea>
132	        </div>
133	        <div class="field">
134	          <label>Labels (type and press Enter)</label>
