137	          </div>
138	          <div class="suggest" id="suggest"></div>
139	        </div>
140	      </div>
141	
142	      <p class="warn" id="warn"></p>
143	      <div class="row-btns">
144	        <button class="save" id="saveBtn" disabled>Save it</button>
145	        <button class="cancel" id="cancelBtn">Cancel</button>
146	        <button class="aside-btn" id="asideBtn">Set aside</button>
147	        <button class="delete" id="deleteBtn">Delete for good</button>
148	      </div>
149	    </div>
150	
151	    <div class="search" id="searchBar"><input id="q" type="text" placeholder="Search your bookmarks…" autocomplete="off" /></div>
152	    <div class="tagbar" id="tagbar"></div>
