159	  <div id="toast"><span id="toastMsg"></span><button id="toastUndo">Undo</button></div>
160	
161	<script>
162	  const bookmarks = [];   // day one — nothing saved yet
163	
164	  function normUrl(u){ return u.trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/+$/,''); }
165	  function findExisting(u, except){ const n=normUrl(u); if(!n) return null; return bookmarks.find(b=>b!==except && b.url && normUrl(b.url)===n); }
166	
167	  const fetchMock = [
168	    { match:"smittenkitchen", title:"The best olive oil cake, ever", source:"Smitten Kitchen", desc:"A one-bowl olive oil cake with a crackly top — plush, citrusy, and impossible to mess up." },
169	    { match:"nytimes", title:"A weeknight sheet-pan chicken dinner", source:"The New York Times", desc:"Everything roasts on one tray: chicken thighs, potatoes and lemon. Minimal cleanup." },
170	    { match:"css-tricks", title:"A complete guide to Flexbox", source:"CSS-Tricks", desc:"The go-to visual reference for the flexbox layout properties, with diagrams for each one." }
171	  ];
172	
173	  let pendingTags=[], editing=null, activeTag=null, deleteArmed=false, viewMode='active', toastTimer=null;
174	  const $ = id => document.getElementById(id);
175	
176	  // ---------- gentle tidying: set aside (reversible) vs delete (permanent), both undoable ----------
177	  function showToast(msg, undoFn){
178	    $('toastMsg').textContent=msg; $('toast').style.display='flex';
179	    $('toastUndo').onclick=()=>{ hideToast(); undoFn(); };
180	    if(toastTimer) clearTimeout(toastTimer); toastTimer=setTimeout(hideToast,6000);
181	  }
182	  function hideToast(){ $('toast').style.display='none'; }
183	  function setAside(b){ b.aside=true; if(activeTag && !bookmarks.some(x=>!x.aside && x.tags.includes(activeTag))) activeTag=null; render(); showToast('Set aside — out of your main list.', ()=>{ b.aside=false; render(); }); }
184	  function bringBack(b){ b.aside=false; render(); showToast('Brought back to your list.', ()=>{ b.aside=true; render(); }); }
185	  function deleteForGood(b){ const i=bookmarks.indexOf(b); if(i<0) return; bookmarks.splice(i,1); if(activeTag && !bookmarks.some(x=>x.tags.includes(activeTag))) activeTag=null; render(); showToast('Deleted for good.', ()=>{ bookmarks.splice(i,0,b); render(); }); }
186	  const list=$('list'), empty=$('empty'), count=$('count'), q=$('q'), tagbar=$('tagbar');
187	
188	  function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
189	  function esc(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
190	  function highlight(text,tokens){const safe=escapeHtml(text);if(!tokens.length)return safe;const re=new RegExp('\\b('+tokens.map(esc).join('|')+')','ig');return safe.replace(re,'<mark>$1</mark>');}
191	
192	  // ---------- add / fuller editor ----------
193	  function guessFromUrl(u){
194	    const hit=fetchMock.find(m=>u.toLowerCase().includes(m.match));
195	    if(hit) return {...hit, autofilled:true};
196	    let host=''; try { host=new URL(u).hostname.replace(/^www\./,''); } catch(e){}
197	    if(!host) return null;
198	    const name=host.split('.')[0].replace(/-/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
199	    return { title:"(couldn't read the title — type it here)", source:name, site:host, desc:'', autofilled:false };
200	  }
201	
202	  function renderChips(){
203	    const box=$('chipsIn'); box.querySelectorAll('.chip-editable').forEach(e=>e.remove());
204	    pendingTags.forEach((t,i)=>{
205	      const c=document.createElement('span'); c.className='chip-editable';
206	      c.innerHTML=`${escapeHtml(t)} <button data-i="${i}">✕</button>`;
207	      c.querySelector('button').addEventListener('click',()=>{ pendingTags.splice(i,1); renderChips(); renderSuggest(); });
208	      box.insertBefore(c,$('labelInput'));
209	    });
210	  }
211	  function renderSuggest(){
212	    const typed=$('labelInput').value.trim().toLowerCase();
213	    let existing=[...new Set(bookmarks.flatMap(b=>b.tags))].filter(t=>!pendingTags.includes(t));
214	    if(typed) existing=existing.filter(t=>t.toLowerCase().includes(typed));
215	    const heading=typed?'Did you mean: ':'Reuse a label: ';
216	    $('suggest').innerHTML = existing.length ? heading+existing.map(t=>`<button data-t="${escapeHtml(t)}">${escapeHtml(t)}</button>`).join('') : '';
217	    $('suggest').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{ pendingTags.push(b.getAttribute('data-t')); $('labelInput').value=''; renderChips(); renderSuggest(); }));
218	  }
219	  function addLabelFromInput(){ const v=$('labelInput').value.trim(); if(v){ const m=[...new Set(bookmarks.flatMap(b=>b.tags))].find(t=>t.toLowerCase()===v.toLowerCase()); const use=m||v; if(!pendingTags.includes(use)) pendingTags.push(use); } $('labelInput').value=''; renderChips(); renderSuggest(); }
220	
221	  function resetDelete(){ deleteArmed=false; $('deleteBtn').classList.remove('armed'); $('deleteBtn').textContent='Delete for good'; }
222	  function openAdder(){ editing=null; $('adder').classList.add('open'); $('adderTitle').textContent='Save a new bookmark'; $('urlLabel').textContent='Paste the link'; $('saveBtn').textContent='Save it'; $('deleteBtn').style.display='none'; $('asideBtn').style.display='none'; $('preview').classList.remove('show'); $('saveBtn').disabled=true; $('url').focus(); }
223	  function openEditor(b){
224	    editing=b; resetDelete();
225	    $('adder').classList.add('open'); $('adderTitle').textContent='Edit details'; $('urlLabel').textContent='The link (its real web address — you can fix it if it moved or is wrong)';
226	    $('dupe').style.display='none'; $('warn').style.display='none';
227	    $('url').value=b.url||'';
228	    $('preview').classList.add('show');
229	    $('fTitle').value=b.title; $('fSite').value=b.source; $('fDesc').value=b.desc||''; $('fNote').value=b.note||'';
230	    $('tFill').textContent=''; $('sFill').textContent=''; $('dFill').textContent='';
231	    pendingTags=[...b.tags]; renderChips(); renderSuggest();
232	    $('saveBtn').disabled=false; $('saveBtn').textContent='Save changes'; $('deleteBtn').style.display='inline-block'; $('asideBtn').style.display='inline-block';
233	    $('adder').scrollIntoView({behavior:'smooth',block:'start'});
234	  }
235	  function closeAdder(){
236	    $('adder').classList.remove('open'); $('preview').classList.remove('show');
237	    $('url').value=''; $('fTitle').value=''; $('fSite').value=''; $('fDesc').value=''; $('fNote').value='';
238	    $('dupe').style.display='none'; $('warn').style.display='none'; editing=null; resetDelete();
239	    $('deleteBtn').style.display='none'; $('asideBtn').style.display='none';
240	    pendingTags=[]; renderChips(); renderSuggest(); $('saveBtn').disabled=true;
241	    $('tFill').textContent=''; $('sFill').textContent=''; $('dFill').textContent='';
242	  }
243	  function flashTo(b){ b._fresh=true; render(); const el=list.querySelector('[data-url="'+(b.url||'').replace(/"/g,'\\"')+'"]'); if(el) el.scrollIntoView({behavior:'smooth',block:'center'}); else window.scrollTo({top:0,behavior:'smooth'}); }
244	
245	  $('addBtn').addEventListener('click',openAdder);
246	  $('cancelBtn').addEventListener('click',closeAdder);
247	
248	  $('url').addEventListener('input',()=>{
249	    if(editing) return;                          // in the editor the link is yours to fix; no auto-fetch
250	    const u=$('url').value.trim();
251	    const existing=u?findExisting(u):null;
252	    if(existing){
253	      $('dupe').style.display='block';
254	      $('dupeText').textContent='You already saved this one — "'+existing.title+'".';
255	      $('openExisting').onclick=()=>{ $('dupe').style.display='none'; openEditor(existing); };
256	      $('preview').classList.remove('show'); $('saveBtn').disabled=true; return;
257	    }
258	    $('dupe').style.display='none';
259	    const g=u?guessFromUrl(u):null;
260	    if(!g){ $('preview').classList.remove('show'); $('saveBtn').disabled=true; return; }
261	    $('preview').classList.add('show');
262	    $('fTitle').value=g.title; $('fSite').value=g.source; $('fDesc').value=g.desc;
263	    const tag=g.autofilled?'filled in for you':'';
264	    $('tFill').textContent=tag; $('sFill').textContent=tag; $('dFill').textContent=tag;
265	    renderSuggest(); $('saveBtn').disabled=false;
266	  });
267	
268	  $('labelInput').addEventListener('keydown',e=>{ if(e.key==='Enter'){ e.preventDefault(); addLabelFromInput(); }});
269	  $('labelInput').addEventListener('input',renderSuggest);
270	
271	  $('saveBtn').addEventListener('click',()=>{
272	    if(editing){
273	      const u=$('url').value.trim();
274	      const clash=findExisting(u, editing);
275	      if(clash){ $('warn').style.display='block'; $('warn').textContent='That link already belongs to another bookmark ("'+clash.title+'"). Give this one a different link.'; return; }
276	      editing.url=u||editing.url;
277	      editing.title=$('fTitle').value.trim()||'(untitled)';
278	      editing.source=$('fSite').value.trim()||'Unknown site';
279	      editing.desc=$('fDesc').value.trim();
280	      editing.note=$('fNote').value.trim();
281	      editing.tags=[...pendingTags];
282	      const ref=editing; closeAdder(); flashTo(ref); return;
283	    }
284	    const u=$('url').value.trim();
285	    const existing=findExisting(u);
286	    if(existing){ closeAdder(); openEditor(existing); return; }
287	    const b={ url:u, title:$('fTitle').value.trim()||'(untitled)', source:$('fSite').value.trim()||'Unknown site',
288	      site:'', desc:$('fDesc').value.trim(), note:$('fNote').value.trim(), date:'Saved just now', tags:[...pendingTags] };
289	    bookmarks.unshift(b); closeAdder(); q.value=''; activeTag=null; flashTo(b);
290	  });
291	
292	  $('asideBtn').addEventListener('click',()=>{ if(!editing) return; const b=editing; closeAdder(); setAside(b); });
293	
294	  $('deleteBtn').addEventListener('click',()=>{
295	    if(!editing) return;
296	    if(!deleteArmed){ deleteArmed=true; $('deleteBtn').classList.add('armed'); $('deleteBtn').textContent='Really delete? Click again'; return; }
297	    const b=editing; closeAdder(); deleteForGood(b);
298	  });
299	
300	  // ---------- find + roundups + inline tidies ----------
301	  function renderTagbar(){
302	    const allTags=[...new Set(bookmarks.flatMap(b=>b.tags))];
303	    tagbar.innerHTML = (allTags.length?'<span class="label">Round up:</span>':'') + allTags.map(t=>
304	      `<button class="filter ${t===activeTag?'on':''}" data-tag="${escapeHtml(t)}">${escapeHtml(t)}</button>`).join('')
305	      + (activeTag?'<button class="clear" id="clearBtn">✕ Show all again</button>':'');
306	    tagbar.querySelectorAll('.filter').forEach(el=>el.addEventListener('click',()=>{ const t=el.getAttribute('data-tag'); activeTag=(activeTag===t)?null:t; render(); }));
307	    const cb=$('clearBtn'); if(cb) cb.addEventListener('click',()=>{ activeTag=null; render(); });
308	  }
309	
310	  function renderAsideBar(){
311	    const n=bookmarks.filter(b=>b.aside).length; const bar=$('asideBar');
312	    if(viewMode==='aside'){ bar.innerHTML='<a href="#" id="backActive">← Back to my list</a>'; $('backActive').onclick=e=>{e.preventDefault(); viewMode='active'; render();}; }
313	    else if(n>0){ bar.innerHTML='<a href="#" id="toAside">🗂 Set aside ('+n+')</a>'; $('toAside').onclick=e=>{e.preventDefault(); viewMode='aside'; render();}; }
314	    else bar.innerHTML='';
315	  }
316	
317	  function renderAside(){
318	    $('searchBar').style.display='none'; tagbar.innerHTML='';
319	    const aside=bookmarks.filter(b=>b.aside);
320	    count.textContent = aside.length+(aside.length===1?' thing set aside':' things set aside');
321	    if(!aside.length){ list.innerHTML=''; empty.style.display='block'; empty.innerHTML='Nothing set aside.'; return; }
322	    empty.style.display='none';
323	    list.innerHTML = aside.map(b=>`
324	      <li data-url="${escapeHtml(b.url||'')}" style="opacity:.85;">
325	        <p class="title">${escapeHtml(b.title)}</p>
326	        <p class="site">${escapeHtml(b.source)}</p>
327	        ${b.note?`<p class="desc" style="border-left:3px solid #c7d2fe; padding-left:10px; color:#3730a3;"><em>${escapeHtml(b.note)}</em></p>`:''}
328	        <div class="row-btns" style="margin-top:8px;">
329	          <button class="save bringback" data-url="${escapeHtml(b.url||'')}">Bring back</button>
330	          <button class="cancel delperm" data-url="${escapeHtml(b.url||'')}">Delete for good</button>
331	        </div>
332	      </li>`).join('');
333	    list.querySelectorAll('.bringback').forEach(el=>el.addEventListener('click',()=>{ const b=bookmarks.find(x=>(x.url||'')===el.getAttribute('data-url')&&x.aside); if(b) bringBack(b); }));
334	    list.querySelectorAll('.delperm').forEach(el=>el.addEventListener('click',()=>{ const b=bookmarks.find(x=>(x.url||'')===el.getAttribute('data-url')&&x.aside); if(b) deleteForGood(b); }));
335	  }
336	
337	  function render(){
338	    renderAsideBar();
339	    if(viewMode==='aside'){ renderAside(); return; }
340	    $('searchBar').style.display='';
341	    const term=q.value;
342	    const tokens=term.trim().toLowerCase().split(/\s+/).filter(Boolean);
343	    const tokenRes=tokens.map(tok=>new RegExp('\\b'+esc(tok),'i'));
344	    const matches=bookmarks.filter(b=>{
345	      if(b.aside) return false;
346	      if(activeTag && !b.tags.includes(activeTag)) return false;
347	      if(!tokens.length) return true;
348	      const hay=(b.title+' '+b.desc+' '+(b.note||'')+' '+b.source+' '+b.site).toLowerCase();
349	      return tokenRes.every(re=>re.test(hay));
350	    });
351	    renderTagbar();
352	
353	    const totalActive = bookmarks.filter(b=>!b.aside).length;
354	    const anySaved = bookmarks.length>0;
355	    // Day one: nothing saved at all — welcome, and don't show a search box with nothing to search.
356	    $('searchBar').style.display = anySaved ? '' : 'none';
357	    if(matches.length===0){
358	      list.innerHTML=''; empty.style.display='block'; count.textContent='';
359	      if(!anySaved){
360	        empty.innerHTML = '<div style="font-size:34px; margin-bottom:8px;">🔖</div>'
361	          + '<strong style="display:block; font-size:17px; margin-bottom:6px;">Nothing saved yet</strong>'
362	          + 'Paste your first link with <strong>＋ Add bookmark</strong> above,<br>and it\'ll live here where you can always find it.';
363	      } else if(totalActive===0){
364	        empty.innerHTML = 'Everything is tucked away in <strong>🗂 Set aside</strong>.<br>Your main list is clear.';
365	      } else if(q.value.trim() || activeTag){
366	        empty.innerHTML = 'Nothing to show for that.';
367	      } else {
368	        empty.innerHTML = 'Nothing here.';
369	      }
370	      return;
371	    }
372	    empty.style.display='none';
373	    count.textContent = matches.length + (matches.length===1?' bookmark':' bookmarks') + (activeTag?' tagged "'+escapeHtml(activeTag)+'"':'');
374	
375	    list.innerHTML = matches.map(b=>`
376	      <li class="${b._fresh?'fresh':''}" data-url="${escapeHtml(b.url||'')}">
377	        <div class="card-head">
378	          <p class="title"><a href="#" onclick="return false;">${highlight(b.title,tokens)}</a></p>
379	          <button class="edit-btn" data-url="${escapeHtml(b.url||'')}">Edit details</button>
380	        </div>
381	        <p class="site">${highlight(b.source,tokens)}</p>
382	        ${b.desc?`<p class="desc">${highlight(b.desc,tokens)}</p>`:''}
383	        ${b.note ? `<div class="note-edit" contenteditable="true" data-url="${escapeHtml(b.url||'')}">${highlight(b.note,tokens)}</div>` : `<button class="add-note" data-url="${escapeHtml(b.url||'')}">＋ add a note</button>`}
384	        <p class="date">${escapeHtml(b.date)}</p>
385	        <div class="tags" data-url="${escapeHtml(b.url||'')}">${b.tags.map(t=>`<span class="tag ${t===activeTag?'on':''}" data-tag="${escapeHtml(t)}">${escapeHtml(t)}<span class="x" data-remove="${escapeHtml(t)}">×</span></span>`).join('')}<span class="add-label">＋ label</span></div>
386	      </li>`).join('');
387	
388	    list.querySelectorAll('.edit-btn').forEach(el=>el.addEventListener('click',()=>{ const b=bookmarks.find(x=>(x.url||'')===el.getAttribute('data-url')); if(b) openEditor(b); }));
389	    list.querySelectorAll('.tag').forEach(el=>el.addEventListener('click',e=>{ if(e.target.classList.contains('x')) return; const t=el.getAttribute('data-tag'); activeTag=(activeTag===t)?null:t; render(); window.scrollTo({top:0,behavior:'smooth'}); }));
390	    list.querySelectorAll('.tag .x').forEach(el=>el.addEventListener('click',e=>{ e.stopPropagation(); const li=el.closest('li'); const b=bookmarks.find(x=>(x.url||'')===li.getAttribute('data-url')); const t=el.getAttribute('data-remove'); if(b){ b.tags=b.tags.filter(x=>x!==t); if(activeTag&&!bookmarks.some(x=>x.tags.includes(activeTag))) activeTag=null; render(); }}));
391	    function wireNote(el){
392	      el.addEventListener('blur',()=>{ const li=el.closest('li'); const b=bookmarks.find(x=>(x.url||'')===li.getAttribute('data-url')); if(b){ const v=el.textContent.trim(); if(v!==(b.note||'')){ b.note=v; render(); } else if(!v){ render(); } }});
393	    }
394	    list.querySelectorAll('.note-edit').forEach(wireNote);
395	    // empty cards show only a quiet link; clicking it opens an editable note in place
396	    list.querySelectorAll('.add-note').forEach(el=>el.addEventListener('click',()=>{
397	      const div=document.createElement('div'); div.className='note-edit'; div.setAttribute('contenteditable','true');
398	      el.replaceWith(div); wireNote(div); div.focus();
399	    }));
400	    list.querySelectorAll('.add-label').forEach(el=>el.addEventListener('click',()=>{
401	      const li=el.closest('li'); const b=bookmarks.find(x=>(x.url||'')===li.getAttribute('data-url'));
402	      const existing=[...new Set(bookmarks.flatMap(x=>x.tags))];
403	      const inp=document.createElement('input'); inp.className='add-label-input'; inp.placeholder='label…';
404	      const dl=document.createElement('datalist'); dl.id='dl-'+Math.abs(hashStr(b.url||''));
405	      existing.forEach(t=>{const o=document.createElement('option');o.value=t;dl.appendChild(o);});
406	      inp.setAttribute('list',dl.id); el.replaceWith(inp); inp.parentNode.appendChild(dl); inp.focus();
407	      let done=false;
408	      const commit=()=>{ if(done) return; done=true; let v=inp.value.trim(); if(v){ const m=existing.find(t=>t.toLowerCase()===v.toLowerCase()); v=m||v; if(!b.tags.includes(v)) b.tags.push(v); } render(); };
409	      inp.addEventListener('keydown',e=>{ if(e.key==='Enter'){ e.preventDefault(); commit(); } if(e.key==='Escape'){ done=true; render(); }});
410	      inp.addEventListener('blur',commit);
411	    }));
412	    bookmarks.forEach(b=>{ if(b._fresh) delete b._fresh; });
413	  }
414	  function hashStr(s){let h=0;for(let i=0;i<s.length;i++){h=(h*31+s.charCodeAt(i))|0;}return h;}
415	
416	  q.addEventListener('input',render);
417	  render();
418	</script>
419	</body>
420	</html>
