function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function esc(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function highlight(text,tokens){const safe=escapeHtml(text);if(!tokens.length)return safe;const re=new RegExp('\\b('+tokens.map(esc).join('|')+')','ig');return safe.replace(re,'<mark>$1</mark>');}

// ---------- add / fuller editor ----------
// Does this even look like a web address? (tolerant of a missing https://)
function asUrl(u){
  let s=u.trim(); if(!s) return null;
  if(!/^https?:\/\//i.test(s)) s='https://'+s;
  try { const url=new URL(s); return url.hostname.includes('.') ? url : null; } catch(e){ return null; }
}
function guessFromUrl(u){
  const url=asUrl(u); if(!url) return null;
  const hit=fetchMock.find(m=>u.toLowerCase().includes(m.match));
  if(hit) return {...hit, autofilled:true};
  const host=url.hostname.replace(/^www\./,'');
  const name=host.split('.')[0].replace(/-/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
  return { title:'', source:name, site:host, desc:'', autofilled:false };  // couldn't read the page
}

function renderChips(){
  const box=$('chipsIn'); box.querySelectorAll('.chip-editable').forEach(e=>e.remove());
  pendingTags.forEach((t,i)=>{
    const c=document.createElement('span'); c.className='chip-editable';
    c.innerHTML=`${escapeHtml(t)} <button data-i="${i}">✕</button>`;
    c.querySelector('button').addEventListener('click',()=>{ pendingTags.splice(i,1); renderChips(); renderSuggest(); });
    box.insertBefore(c,$('labelInput'));
  });
}
function renderSuggest(){
  const typed=$('labelInput').value.trim().toLowerCase();
  let existing=[...new Set(bookmarks.flatMap(b=>b.tags))].filter(t=>!pendingTags.includes(t));
  if(typed) existing=existing.filter(t=>t.toLowerCase().includes(typed));
  const heading=typed?'Did you mean: ':'Reuse a label: ';
  $('suggest').innerHTML = existing.length ? heading+existing.map(t=>`<button data-t="${escapeHtml(t)}">${escapeHtml(t)}</button>`).join('') : '';
  $('suggest').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{ pendingTags.push(b.getAttribute('data-t')); $('labelInput').value=''; renderChips(); renderSuggest(); }));
}
function addLabelFromInput(){ const v=$('labelInput').value.trim(); if(v){ const m=[...new Set(bookmarks.flatMap(b=>b.tags))].find(t=>t.toLowerCase()===v.toLowerCase()); const use=m||v; if(!pendingTags.includes(use)) pendingTags.push(use); } $('labelInput').value=''; renderChips(); renderSuggest(); }

function resetDelete(){ deleteArmed=false; $('deleteBtn').classList.remove('armed'); $('deleteBtn').textContent='Delete for good'; }
function openAdder(){ editing=null; $('adder').classList.add('open'); $('adderTitle').textContent='Save a new bookmark'; $('urlLabel').textContent='Paste the link'; $('saveBtn').textContent='Save it'; $('deleteBtn').style.display='none'; $('asideBtn').style.display='none'; $('preview').classList.remove('show'); $('saveBtn').disabled=true; $('url').focus(); }
function openEditor(b){
  editing=b; resetDelete();
  $('adder').classList.add('open'); $('adderTitle').textContent='Edit details'; $('urlLabel').textContent='The link (its real web address — you can fix it if it moved or is wrong)';
  $('dupe').style.display='none'; $('warn').style.display='none';
  $('url').value=b.url||'';
  $('preview').classList.add('show');
  $('fTitle').value=b.title; $('fSite').value=b.source; $('fDesc').value=b.desc||''; $('fNote').value=b.note||'';
  $('tFill').textContent=''; $('sFill').textContent=''; $('dFill').textContent='';
  pendingTags=[...b.tags]; renderChips(); renderSuggest();
  $('saveBtn').disabled=false; $('saveBtn').textContent='Save changes'; $('deleteBtn').style.display='inline-block'; $('asideBtn').style.display='inline-block';
  $('adder').scrollIntoView({behavior:'smooth',block:'start'});
}
function closeAdder(){
  $('adder').classList.remove('open'); $('preview').classList.remove('show');
  $('url').value=''; $('fTitle').value=''; $('fSite').value=''; $('fDesc').value=''; $('fNote').value='';
  $('dupe').style.display='none'; $('warn').style.display='none'; $('urlHint').style.display='none'; editing=null; resetDelete();
  $('deleteBtn').style.display='none'; $('asideBtn').style.display='none';
  pendingTags=[]; renderChips(); renderSuggest(); $('saveBtn').disabled=true;
  $('tFill').textContent=''; $('sFill').textContent=''; $('dFill').textContent='';
}
function flashTo(b){ b._fresh=true; render(); const el=list.querySelector('[data-url="'+(b.url||'').replace(/"/g,'\\"')+'"]'); if(el) el.scrollIntoView({behavior:'smooth',block:'center'}); else window.scrollTo({top:0,behavior:'smooth'}); }

$('addBtn').addEventListener('click',openAdder);
$('cancelBtn').addEventListener('click',closeAdder);

$('url').addEventListener('input',()=>{
  if(editing) return;                          // in the editor the link is yours to fix; no auto-fetch
  const u=$('url').value.trim();
  if(!u){ $('urlHint').style.display='none'; $('dupe').style.display='none'; $('preview').classList.remove('show'); $('saveBtn').disabled=true; return; }
  const existing=findExisting(u);
  if(existing){
    $('urlHint').style.display='none'; $('dupe').style.display='block';
    $('dupeText').textContent='You already saved this one — "'+existing.title+'".';
    $('openExisting').onclick=()=>{ $('dupe').style.display='none'; openEditor(existing); };
    $('preview').classList.remove('show'); $('saveBtn').disabled=true; return;
  }
  $('dupe').style.display='none';
  if(!asUrl(u)){                               // not a link at all
    $('urlHint').style.display='block'; $('urlHint').style.color='#b45309';
    $('urlHint').textContent="That doesn't look like a web link yet — a bookmark needs an address (like https://…) to take you back to.";
    $('preview').classList.remove('show'); $('saveBtn').disabled=true; return;
  }
  const g=guessFromUrl(u);
  $('preview').classList.add('show');
  $('fTitle').value=g.title; $('fSite').value=g.source; $('fDesc').value=g.desc;
  if(g.autofilled){
    $('urlHint').style.display='none';
